IF DB_ID(N'AdDatabase') IS NULL CREATE DATABASE AdDatabase;
GO
USE AdDatabase;
GO
IF OBJECT_ID(N'dbo.Roles',N'U') IS NOT NULL RETURN;
CREATE TABLE Roles(Id int IDENTITY PRIMARY KEY,Name nvarchar(50) NOT NULL UNIQUE);
CREATE TABLE Users(Id int IDENTITY PRIMARY KEY,Email nvarchar(256) NOT NULL UNIQUE,PasswordHash nvarchar(500) NOT NULL,UserName nvarchar(100) NOT NULL UNIQUE,Status nvarchar(20) NOT NULL DEFAULT 'Active',RoleId int NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Users_Roles FOREIGN KEY(RoleId) REFERENCES Roles(Id));
CREATE TABLE Profiles(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL UNIQUE,FullName nvarchar(200),Phone nvarchar(30),ImageUrl nvarchar(1000),Bio nvarchar(2000),CONSTRAINT FK_Profiles_Users FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE TABLE Sessions(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,RefreshToken nvarchar(500) NOT NULL,ExpiresAt datetime2 NOT NULL,RevokedAt datetime2 NULL,CONSTRAINT FK_Sessions_Users FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE TABLE VerificationCodes(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,Code nvarchar(20) NOT NULL,Type nvarchar(20) NOT NULL DEFAULT 'Email',ExpiresAt datetime2 NOT NULL,IsUsed bit NOT NULL DEFAULT 0,CONSTRAINT FK_VerificationCodes_Users FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE TABLE Cities(Id int IDENTITY PRIMARY KEY,Name nvarchar(150) NOT NULL);
CREATE TABLE Regions(Id int IDENTITY PRIMARY KEY,Name nvarchar(150) NOT NULL,CityId int NOT NULL,CONSTRAINT FK_Regions_Cities FOREIGN KEY(CityId) REFERENCES Cities(Id));
CREATE TABLE Categories(Id int IDENTITY PRIMARY KEY,Name nvarchar(150) NOT NULL,ParentCategoryId int NULL,CONSTRAINT FK_Categories_Parent FOREIGN KEY(ParentCategoryId) REFERENCES Categories(Id));
CREATE TABLE Ads(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,CategoryId int NOT NULL,RegionId int NOT NULL,Title nvarchar(250) NOT NULL,Description nvarchar(max) NOT NULL,Price decimal(18,2) NOT NULL,Status nvarchar(20) NOT NULL DEFAULT 'Pending',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ExpiresAt datetime2 NULL,CONSTRAINT FK_Ads_Users FOREIGN KEY(UserId) REFERENCES Users(Id),CONSTRAINT FK_Ads_Categories FOREIGN KEY(CategoryId) REFERENCES Categories(Id),CONSTRAINT FK_Ads_Regions FOREIGN KEY(RegionId) REFERENCES Regions(Id));
CREATE TABLE AdImages(Id int IDENTITY PRIMARY KEY,AdId int NOT NULL,Url nvarchar(1000) NOT NULL,SortOrder int NOT NULL DEFAULT 0,IsPrimary bit NOT NULL DEFAULT 0,CONSTRAINT FK_AdImages_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id) ON DELETE CASCADE,CONSTRAINT UQ_AdImages_Order UNIQUE(AdId,SortOrder));
CREATE TABLE AdAttributes(Id int IDENTITY PRIMARY KEY,AdId int NOT NULL,[Key] nvarchar(100) NOT NULL,[Value] nvarchar(500) NOT NULL,CONSTRAINT FK_AdAttributes_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id) ON DELETE CASCADE);
CREATE TABLE Tags(Id int IDENTITY PRIMARY KEY,Name nvarchar(100) NOT NULL UNIQUE);
CREATE TABLE AdTags(AdId int NOT NULL,TagId int NOT NULL,CONSTRAINT PK_AdTags PRIMARY KEY(AdId,TagId),CONSTRAINT FK_AdTags_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id) ON DELETE CASCADE,CONSTRAINT FK_AdTags_Tags FOREIGN KEY(TagId) REFERENCES Tags(Id) ON DELETE CASCADE);
CREATE TABLE Businesses(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,RegionId int NOT NULL,Name nvarchar(200) NOT NULL,Description nvarchar(max),IsVerified bit NOT NULL DEFAULT 0,CONSTRAINT FK_Businesses_Users FOREIGN KEY(UserId) REFERENCES Users(Id),CONSTRAINT FK_Businesses_Regions FOREIGN KEY(RegionId) REFERENCES Regions(Id));
CREATE TABLE BusinessCategories(Id int IDENTITY PRIMARY KEY,BusinessId int NOT NULL,CategoryId int NOT NULL,CONSTRAINT UQ_BusinessCategories UNIQUE(BusinessId,CategoryId),CONSTRAINT FK_BusinessCategories_Businesses FOREIGN KEY(BusinessId) REFERENCES Businesses(Id) ON DELETE CASCADE,CONSTRAINT FK_BusinessCategories_Categories FOREIGN KEY(CategoryId) REFERENCES Categories(Id));
CREATE TABLE BusinessItems(Id int IDENTITY PRIMARY KEY,BusinessId int NOT NULL,Name nvarchar(200) NOT NULL,Description nvarchar(max),Price decimal(18,2) NOT NULL,IsUpgradeToAd bit NOT NULL DEFAULT 0,CONSTRAINT FK_BusinessItems_Businesses FOREIGN KEY(BusinessId) REFERENCES Businesses(Id) ON DELETE CASCADE);
CREATE TABLE ItemImages(Id int IDENTITY PRIMARY KEY,BusinessItemId int NOT NULL,Url nvarchar(1000) NOT NULL,SortOrder int NOT NULL DEFAULT 0,CONSTRAINT FK_ItemImages_Items FOREIGN KEY(BusinessItemId) REFERENCES BusinessItems(Id) ON DELETE CASCADE);
CREATE TABLE Conversations(Id int IDENTITY PRIMARY KEY,AdId int NOT NULL,BuyerUserId int NOT NULL,SellerUserId int NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),LastMessageAt datetime2 NULL,CONSTRAINT UQ_Conversations UNIQUE(AdId,BuyerUserId,SellerUserId),CONSTRAINT FK_Conversations_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id),CONSTRAINT FK_Conversations_Buyer FOREIGN KEY(BuyerUserId) REFERENCES Users(Id),CONSTRAINT FK_Conversations_Seller FOREIGN KEY(SellerUserId) REFERENCES Users(Id));
CREATE TABLE Messages(Id int IDENTITY PRIMARY KEY,ConversationId int NOT NULL,SenderUserId int NOT NULL,Body nvarchar(max) NOT NULL,IsRead bit NOT NULL DEFAULT 0,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Messages_Conversations FOREIGN KEY(ConversationId) REFERENCES Conversations(Id) ON DELETE CASCADE,CONSTRAINT FK_Messages_Sender FOREIGN KEY(SenderUserId) REFERENCES Users(Id));
CREATE TABLE MessageAttachments(Id int IDENTITY PRIMARY KEY,MessageId int NOT NULL,Url nvarchar(1000) NOT NULL,ContentType nvarchar(100) NOT NULL,CONSTRAINT FK_MessageAttachments_Messages FOREIGN KEY(MessageId) REFERENCES Messages(Id) ON DELETE CASCADE);
CREATE TABLE Comments(Id int IDENTITY PRIMARY KEY,AdId int NOT NULL,UserId int NOT NULL,Body nvarchar(2000) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Comments_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id) ON DELETE CASCADE,CONSTRAINT FK_Comments_Users FOREIGN KEY(UserId) REFERENCES Users(Id));
CREATE TABLE Ratings(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,RatedUserId int NOT NULL,[Value] tinyint NOT NULL,Comment nvarchar(1000),CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CHK_Ratings_NoSelfRating CHECK(UserId<>RatedUserId),CONSTRAINT CHK_Ratings_Value CHECK([Value] BETWEEN 1 AND 5),CONSTRAINT FK_Ratings_User FOREIGN KEY(UserId) REFERENCES Users(Id),CONSTRAINT FK_Ratings_Rated FOREIGN KEY(RatedUserId) REFERENCES Users(Id));
CREATE TABLE AdFavorites(UserId int NOT NULL,AdId int NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_AdFavorites PRIMARY KEY(UserId,AdId),CONSTRAINT FK_AdFavorites_Users FOREIGN KEY(UserId) REFERENCES Users(Id),CONSTRAINT FK_AdFavorites_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id) ON DELETE CASCADE);
CREATE TABLE Follows(FollowerUserId int NOT NULL,FollowedUserId int NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_Follows PRIMARY KEY(FollowerUserId,FollowedUserId),CONSTRAINT CHK_Follows_NoSelf CHECK(FollowerUserId<>FollowedUserId),CONSTRAINT FK_Follows_Follower FOREIGN KEY(FollowerUserId) REFERENCES Users(Id),CONSTRAINT FK_Follows_Followed FOREIGN KEY(FollowedUserId) REFERENCES Users(Id));
CREATE TABLE News(Id int IDENTITY PRIMARY KEY,Title nvarchar(250) NOT NULL,Body nvarchar(max) NOT NULL,PublishedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Notifications(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,Type nvarchar(50) NOT NULL,Message nvarchar(1000) NOT NULL,IsRead bit NOT NULL DEFAULT 0,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Notifications_Users FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE TABLE Reports(Id int IDENTITY PRIMARY KEY,AdId int NOT NULL,ReporterUserId int NOT NULL,Reason nvarchar(1000) NOT NULL,Status nvarchar(20) NOT NULL DEFAULT 'Open',CONSTRAINT FK_Reports_Ads FOREIGN KEY(AdId) REFERENCES Ads(Id),CONSTRAINT FK_Reports_Users FOREIGN KEY(ReporterUserId) REFERENCES Users(Id));
CREATE TABLE Requests(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,Type nvarchar(50) NOT NULL,Details nvarchar(max) NOT NULL,Status nvarchar(20) NOT NULL DEFAULT 'Pending',CONSTRAINT FK_Requests_Users FOREIGN KEY(UserId) REFERENCES Users(Id));
CREATE TABLE SearchHistories(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,Query nvarchar(500) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_SearchHistories_Users FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE TABLE Verifications(Id int IDENTITY PRIMARY KEY,UserId int NOT NULL,BusinessId int NULL,DocumentUrl nvarchar(1000) NOT NULL,Status nvarchar(20) NOT NULL DEFAULT 'Pending',CONSTRAINT FK_Verifications_Users FOREIGN KEY(UserId) REFERENCES Users(Id),CONSTRAINT FK_Verifications_Businesses FOREIGN KEY(BusinessId) REFERENCES Businesses(Id));
CREATE INDEX IX_Ads_Search ON Ads(Status,CategoryId,RegionId,Price,CreatedAt DESC);
CREATE INDEX IX_Messages_Conversation_CreatedAt ON Messages(ConversationId,CreatedAt);
